import{_ as o,o as a,c as r,a5 as t}from"./chunks/framework.BEZBAInb.js";const h=JSON.parse('{"title":"Logger","description":"","frontmatter":{"title":"Logger","order":4},"headers":[],"relativePath":"en/latest/tutorial/core/logger.md","filePath":"en/latest/tutorial/core/logger.md","lastUpdated":1788455378000}'),n={name:"en/latest/tutorial/core/logger.md"};function i(l,e,d,c,s,g){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="logger-konadologger" tabindex="-1">Logger KonadoLogger <a class="header-anchor" href="#logger-konadologger" aria-label="Permalink to &quot;Logger KonadoLogger&quot;">​</a></h1><h2 id="preface" tabindex="-1">Preface <a class="header-anchor" href="#preface" aria-label="Permalink to &quot;Preface&quot;">​</a></h2><p>KonadoLogger is a logging module based on the Godot Logger implementation. It supports log levels, log formats, log output, log files, and other features, and is used to record Konado runtime log information.</p><h2 id="log-path" tabindex="-1">Log Path <a class="header-anchor" href="#log-path" aria-label="Permalink to &quot;Log Path&quot;">​</a></h2><p>The logical log path is <code>user://konado_log.log</code>. Godot resolves its physical directory for the current operating system and project name; use <code>OS.get_user_data_dir()</code> to inspect it. <code>LOG_FILE_PATH</code> is a built-in constant, so changing the location requires maintaining that change in a customized plugin build.</p><h2 id="on-screen-overlay-log" tabindex="-1">On-Screen Overlay Log <a class="header-anchor" href="#on-screen-overlay-log" aria-label="Permalink to &quot;On-Screen Overlay Log&quot;">​</a></h2><p>When an error occurs, the dialogue scene overlays a log window to show the error and interrupt game execution. Regular warnings are still written to the log file, but they are not presented as runtime failures and do not interrupt the game. To disable the error overlay, set the <code>enable_overlay_log</code> property of <code>KonadoDialogueManager</code> to <code>false</code>.</p><h2 id="log-callback" tabindex="-1">Log Callback <a class="header-anchor" href="#log-callback" aria-label="Permalink to &quot;Log Callback&quot;">​</a></h2><p>A <code>KonadoLogger</code> instance emits <code>error_caught(msg)</code> and <code>message_caught(message, error)</code>. When <code>KonadoDialogueManager</code> enters the scene tree, it creates and registers an internal logger with Godot and uses <code>error_caught</code> to drive its overlay; the logger is not a global autoload. A custom integration that creates another <code>KonadoLogger</code> must register it with <code>OS.add_logger()</code> and call <code>OS.remove_logger()</code> before freeing it to avoid duplicate logging or stale instances.</p><h2 id="runtime-failures" tabindex="-1">Runtime Failures <a class="header-anchor" href="#runtime-failures" aria-label="Permalink to &quot;Runtime Failures&quot;">​</a></h2><p>When an atomic instruction fails, <code>KonadoDialogueManager</code> writes one final error and emits <code>runtime_failure_reported(failure)</code>. The payload contains a stable error code, operation, related resource, underlying cause, source path and line, instruction ID, opcode, and program counter for crash reporting or custom debugging UI. <code>runtime_failed(message, instruction_id, source_line)</code> remains available as the compact interface.</p>',11)])])}const p=o(n,[["render",i]]);export{h as __pageData,p as default};
